        Row("undo", "Undo", "The PC itself", "both", "Command-Only (Runs When You Ask — No Switch Needed)", "The changes you can still undo.", "undo that", "Say, for example: \"undo that\"", "Settings, All features and abilities (planned)", listOf(), listOf(), false, "", "", "not-a-setting", false),
