    /** The five approved label strings, exactly as the PC sends them. */
    val LABELS: List<String> = ROWS.map { it.label }.distinct()

    private val BY_ID: Map<String, Row> = ROWS.associateBy { it.id }

    fun row(id: String): Row? = BY_ID[id]

    /** The rows whose label is this one of the five. */
    fun withLabel(label: String): List<Row> = ROWS.filter { it.label == label }
}
